#pragma once

#include <cstddef>
#include <cstdint>

/**
 * Water polygons for one area, generated by
 * scripts/build_water.py from OpenStreetMap water areas and coastline (ODbL).
 *
 * Coordinates are degrees x 1e5. The data covers a square of +/- kHalfSpan
 * around kCenter; outside it the radar simply draws no water.
 */
namespace data::water {

struct Vertex {
  int32_t lat_e5;
  int32_t lon_e5;
};

struct Path {
  const Vertex* points;
  size_t count;
};

extern const int32_t kCenterLatE5;
extern const int32_t kCenterLonE5;
extern const int32_t kHalfSpanLatE5;
extern const int32_t kHalfSpanLonE5;

/** Closed rings (last vertex connects back to the first). */
extern const Path kWaterPolygons[];
extern const size_t kWaterPolygonCount;

}  // namespace data::water
